  SELECT booking_id, hut_id, party, check_in, nights - 1 FROM bookings WHERE status <> 'cancelled'
  UNION ALL SELECT booking_id, hut_id, party, date(night, '+1 day'), left - 1 FROM n WHERE left > 0
)
